namespace VinsPDF {
internal static class Version028Tests {
 internal static void Assert(bool b,string message){if(!b)throw new Exception(message);}
 public static int Run(string[] args){string dir=args[1];Directory.CreateDirectory(dir);try{using(var e=new PdfEngine()){e.Open(args[2]);var style=new TextStyle{Size=20,Bold=true,Italic=true,Underline=true,Strike=true,Highlight=Color.Yellow,Ink=Color.DarkBlue,LineHeight=1.6f,ParagraphGap=8,CharacterSpacing=.3f,BoxWidth=250};int id=e.PutTextBlock(0,new int[0],"Styled text",style,new PointF(.15f,.4f));var text=TextLines.Group(e.GetObjects(0).Objects,e.Sizes[0],true).Single(o=>o.Text=="Styled text");Assert(text.Ids.Length==14,"Text decorations not grouped with characters: "+text.Ids.Length);Assert(text.Style!=null&&text.Style.Strike&&text.Style.Underline&&text.Style.Bold&&text.Style.Highlight.HasValue&&text.Style.Highlight.Value.ToArgb()==Color.Yellow.ToArgb(),"Style metadata missing");using(var b=e.Preview(0,0,1000)){b.Save(Path.Combine(dir,"decorated.png"));int yellow=0;for(int y=0;y<b.Height;y+=2)for(int x=0;x<b.Width;x+=2){Color c=b.GetPixel(x,y);if(c.R>240&&c.G>240&&c.B<50)yellow++;}Assert(yellow>200,"Highlight did not render");}
 var original=text.Bounds;var moved=original;moved.Offset(.12f,.1f);e.TransformObjects(0,text.Ids,original,moved);e.RotateObjects(0,text.Ids,moved,30);using(var b=e.Preview(0,0,1000))b.Save(Path.Combine(dir,"decorated-rotated.png"));e.DeleteObjects(0,text.Ids);Assert(!e.GetObjects(0).Objects.Any(o=>text.Ids.Contains(o.Id)),"Delete left text active");using(var b=e.Preview(0,0,1000)){int yellow=0;for(int y=0;y<b.Height;y+=3)for(int x=0;x<b.Width;x+=3){Color c=b.GetPixel(x,y);if(c.R>240&&c.G>240&&c.B<50)yellow++;}Assert(yellow==0,"Delete left orphan highlight");}e.UndoEdit(false);e.UndoEdit(false);e.UndoEdit(false);
 e.PutTextBlock(0,new int[0],"First list item\nSecond list item",new TextStyle{Size=14,ListKind=1},new PointF(.15f,.55f));e.PutTextBlock(0,new int[0],"This sentence wraps across several lines in a narrow text box.",new TextStyle{Size=14,Wrap=true,BoxWidth=120,Alignment=3},new PointF(.6f,.6f));var grouped=TextLines.Group(e.GetObjects(0).Objects,e.Sizes[0],true);Assert(grouped.Any(o=>o.Text=="• First list item"),"Bullets missing");Assert(grouped.Count(o=>o.Bounds.X>.59&&o.Bounds.Y>.5)>2,"Text did not wrap");
 string saved=Path.Combine(dir,"styled-028.pdf");e.SaveCopy(saved);text=TextLines.Group(e.GetObjects(0).Objects,e.Sizes[0],true).Single(o=>o.Text=="Styled text");Assert(text.Ids.Length==14&&text.Style.Strike&&text.Style.Underline&&Math.Abs(text.Style.LineHeight-1.6f)<.01f,"Saved style lost");using(var b=e.Preview(0,0,1000))b.Save(Path.Combine(dir,"styled-reopened-028.png"));
 foreach(string ext in new[]{"png","jpg","tif","bmp"}){string output=Path.Combine(dir,"image."+ext);e.ExportImages(output,new[]{1,0},ext,72,80,true);var paths=PdfEngine.ImageTargets(output,new[]{1,0});Assert(paths.Length==2&&paths.All(File.Exists),"Image export missing");using(var b=new Bitmap(paths[0])){Assert(b.Width==(int)e.Sizes[1].Width&&b.Height==(int)e.Sizes[1].Height,"Image dimensions wrong");for(int y=0;y<b.Height;y+=11)for(int x=0;x<b.Width;x+=11){var c=b.GetPixel(x,y);Assert(Math.Abs(c.R-c.G)<5&&Math.Abs(c.R-c.B)<5,"Greyscale failed");}}}
 e.ExportReduced(Path.Combine(dir,"reduced-028.pdf"),new[]{1},96,70,true);using(var reduced=new PdfEngine()){reduced.Open(Path.Combine(dir,"reduced-028.pdf"));Assert(reduced.Count==1&&reduced.GetObjects(0).Objects.All(o=>o.Kind==3),"Reduced PDF wrong");}bool rejected=false;try{e.ExportPixelSize(0,600);}catch(IOException){rejected=true;}Assert(rejected,"Oversize raster was not rejected");
 e.ExportPages(Path.Combine(dir,"organised-028.pdf"),new[]{1,0},new[]{1,3});using(var sorted=new PdfEngine()){sorted.Open(Path.Combine(dir,"organised-028.pdf"));Assert(sorted.Count==2&&sorted.Sizes[0].Width>sorted.Sizes[0].Height,"Organise export wrong");}}
 File.WriteAllText(Path.Combine(dir,"engine-028.txt"),"PASS: text decorations and style persistence; linked move, rotate, delete and undo; bullet lists, wrapping and justification; PNG/JPEG/TIFF/BMP dimensions and greyscale; reduced PDF and page range; raster memory limit; organised page rotation/order.");return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(dir,"engine-028.txt"),"FAIL "+ex);return 1;}}
 internal static void Mouse(Control c,string method,Point p){typeof(Control).GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(c,new object[]{new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0)});}
 internal static void Capture(Control c,string path){using(var b=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(path);}}
}
