 case 0:ToggleEditing();break;
 case 1:Version028Tests.Assert(palette.Width<=240&&palette.Height<450,"Palette not compact");Version028Tests.Capture(palette,Path.Combine(V028Directory,"palette-collapsed.png"));BeginInline(null);inlineText.Text="VinsPDF 0.28 resizable text editing";textStyle.Size=18;textStyle.Highlight=Color.Yellow;textStyle.Underline=true;textStyle.Ink=Color.DarkBlue;palette.SetStyle(textStyle);UpdateInlineFont();int width=inlineFrame.Width;Version028Tests.Mouse(inlineFrame,"OnMouseDown",new Point(width-2,inlineFrame.Height-2));Version028Tests.Mouse(inlineFrame,"OnMouseMove",new Point(width+110,inlineFrame.Height+65));Version028Tests.Mouse(inlineFrame,"OnMouseUp",new Point(inlineFrame.Width-2,inlineFrame.Height-2));Version028Tests.Assert(inlineFrame.Width>width&&inlineResized,"Inline resize failed");Version028Tests.Capture(palette,Path.Combine(V028Directory,"palette-font.png"));Version028Tests.Capture(TopLevelControl,Path.Combine(V028Directory,"inline.png"));CommitInline();break;
