 case 6:Version028Tests.Assert(camera==canvas.PageRectangle,"Undo moved camera");var item=canvas.Objects.First(o=>o.Text.StartsWith("VinsPDF 0.28"));canvas.Selected=item;canvas.Selection.Clear();canvas.Selection.Add(item);var box=canvas.SelectionRect(item.Bounds);Point a=new Point(box.Left+box.Width/4,box.Top+box.Height/2);canvas.TestDrag(a,new Point(box.Right+20,box.Bottom+20));Version028Tests.Assert(!editBusy&&canvas.Selection.Count>0,"Body drag in select moved object");TestSavePrompt(DialogResult.Cancel,false);BeginInline(null);inlineText.Text="Saved on closing";currentPath=Path.Combine(V028Directory,"close-saved.pdf");savedOnce=true;TestSavePrompt(DialogResult.Yes,true);Version028Tests.Assert(!dirty&&inlineText==null,"Saved state wrong");break;
 case 7:BeginInline(null);inlineText.Text="Discard me";TestSavePrompt(DialogResult.No,true);Version028Tests.Assert(inlineText==null,"Discard left inline edit");TestToolDialogs028();TestOrganiserRequests028();palette.ExpandAllForTest();Version028Tests.Capture(palette,Path.Combine(V028Directory,"palette-scrolled.png"));break;
 case 8:BeginInline(null);inlineText.Text="Recoverable failed save";using(var dismiss=new Timer{Interval=150}){dismiss.Tick+=delegate{foreach(Form f in Application.OpenForms)if(f.Text=="Save failed"){dismiss.Stop();f.Close();break;}};dismiss.Start();Version028Tests.Assert(!SaveBeforeClose(Path.Combine(V028Directory,"missing-folder","fail.pdf"))&&dirty,"Failed save lost changes");}Version028Tests.Assert(SaveBeforeClose(Path.Combine(V028Directory,"recovered.pdf")),"Save recovery failed");break;
 case 9:BeginInline(null);CancelInline();Version028Tests.Capture(TopLevelControl,Path.Combine(V028Directory,"editor.png"));Trace("PASS 028 compact palette, resize inline frame, Select centre move/corner resize/rotation, unchanged camera on undo, body marquee, Save/Don't save/Cancel, organiser drag, themed tools and export dialog");timer.Stop();timer.Dispose();dirty=false;WindowSession.Current.CloseAll();break;
 }}catch(Exception ex){Trace("FAIL 028 stage="+(stage-1)+" "+ex);timer.Stop();CancelInline();dirty=false;WindowSession.Current.CloseAll();}finally{processing=false;}};timer.Start();}
 void TestSavePrompt(DialogResult choice,bool expected){using(var t=new Timer{Interval=120}){t.Tick+=delegate{foreach(Form form in Application.OpenForms)if(form is SaveChangesDialog){Version028Tests.Capture(form,Path.Combine(V028Directory,"save-changes.png"));t.Stop();form.DialogResult=choice;break;}};t.Start();Version028Tests.Assert(ConfirmDiscard()==expected,"Save prompt result wrong");}}
 void TestOrganiserRequests028(){bool complete=false;int ticks=0;using(var timer=new Timer{Interval=200}){timer.Tick+=delegate{var dialog=Application.OpenForms.OfType<OrganiseDialog>().FirstOrDefault();if(dialog==null)return;if(++ticks>1200){timer.Stop();dialog.DialogResult=DialogResult.Cancel;return;}if(!dialog.Grid.VisiblePages.All(dialog.Grid.HasImage))return;Version028Tests.Capture(dialog,Path.Combine(V028Directory,"organiser-loaded.png"));complete=true;timer.Stop();dialog.DialogResult=DialogResult.Cancel;};timer.Start();OrganisePages();Version028Tests.Assert(complete,"Organiser thumbnail queue failed");}}
 void TestToolDialogs028(){using(var d=new ExportOptions(sizes.Length,pageIndex)){d.Show(TopLevelControl);d.PreviewFormat(3);Version028Tests.Capture(d,Path.Combine(V028Directory,"export-options.png"));d.Close();}using(var d=new OrganiseDialog(sizes.Length)){d.Show(TopLevelControl);foreach(var pair in thumbs.Take(15))d.Grid.SetImage(pair.Key,(Bitmap)pair.Value.Clone());var a=d.Grid.Card(0);var b=d.Grid.Card(1);Version028Tests.Mouse(d.Grid,"OnMouseDown",new Point(a.Left+40,a.Top+40));Version028Tests.Mouse(d.Grid,"OnMouseMove",new Point(b.Right-10,b.Top+40));Version028Tests.Mouse(d.Grid,"OnMouseUp",new Point(b.Right-10,b.Top+40));Version028Tests.Assert(d.Grid.Pages[0].Index==1&&d.Grid.Pages[1].Index==0,"Thumbnail drag order wrong");d.Grid.Rotate(1);Version028Tests.Capture(d,Path.Combine(V028Directory,"organiser.png"));d.Close();}}
